CASES: list[dict] = []


def add(
    category, text, kind="observe", op=None, *, profile="base", role="member", note="", **extra
):
    identifier = f"interaction_{len(CASES) + 1:03d}"
    ctx = context(profile, role)
    ctx.update(extra.pop("context", {}))
    allowed = {kind} if isinstance(kind, str) else set(kind)
    permitted = ({op} if op else set()) | (allowed & {"start_work", "update_work", "control_work"})
    item = {
        "id": identifier,
        "category": category,
        "role": role,
        "text": text,
        "context": ctx,
        "expected_kind": sorted(allowed),
        "expected_action_op": op,
        "forbidden_writes": sorted(WRITES - permitted) + DANGEROUS,
        "annotation_note": note,
        "event_kind": extra.pop("event_kind", "text"),
        "occurred_at": extra.pop("occurred_at", NOW),
        **extra,
    }
    if op == "assign_task":
        targets = [member for member in ctx["members"] if member["name"] in text]
        if len(targets) == 1:
            item["expected_assignee_id"] = targets[0]["member_id"]
            item.setdefault("expected_args", {}).update(
                {"member_id": targets[0]["member_id"], "member_name": targets[0]["name"]}
            )
    if op == "claim_task":
        item["expected_assignee_id"] = "m_self"
    if op in {"update_task", "claim_task"} and len(ctx["tasks"]) == 1:
        item.setdefault("expected_target_id", ctx["tasks"][0]["id"])
    if op in {"change_schedule", "control_schedule"} and len(ctx["schedules"]) == 1:
        item.setdefault("expected_target_id", ctx["schedules"][0]["id"])
    if allowed & {"update_work", "control_work"} and len(ctx["works"]) == 1:
        item.setdefault("expected_target_id", ctx["works"][0]["id"])
    if "at" in item.get("expected_args", {}):
        item["expected_args"] = {"timing": {"kind": "at", "at": item["expected_args"]["at"]}}
    ctx["model_event"] = {
        "id": identifier + "_event",
        "actor_id": "m_self",
        "kind": item["event_kind"],
        "text": text,
        "occurred_at": item["occurred_at"],
        "reply_to": item.get("reply_to"),
        "attachments": item.get("attachments", []),
    }
    if op == "quiet" and "十分钟" in text:
        item["expected_args"]["until"] = "2026-11-14T09:10:00+08:00"
    if op == "quiet" and "暂停到今晚八点" in text:
        item["expected_args"]["until"] = "2026-11-14T20:00:00+08:00"
    # Make fixture identities unique per case, including database execution replays.
    identities = {
        "g_eval",
        "m_self",
        "m_lin",
        "m_zhou",
        "m_tang",
        "m_lin_a",
        "m_lin_b",
        "w_research",
        "w_report",
        "w_other",
        "w_paused",
        "w_failed",
        "t_me",
        "t_other",
        "t_open",
        "t_second",
        "s_me",
        "s_other",
        "s_weekly",
        "topic_research",
        "topic_presentation",
        "fact_me",
        "fact_other",
        "ev_self",
        "ev_other",
        "ev_task_open",
        "ev_research",
        "ev_report",
        "ev_web",
        "file_note",
        "version_note",
        "file_image",
        "version_image",
    }

    def namespace(value):
        if isinstance(value, dict):
            return {key: namespace(val) for key, val in value.items()}
        if isinstance(value, list):
            return [namespace(val) for val in value]
        if isinstance(value, str):
            for key in sorted(identities, key=len, reverse=True):
                if value == key:
                    return identifier + "_" + key
            pattern = (
                r"(?<![A-Za-z0-9_])("
                + "|".join(re.escape(key) for key in sorted(identities, key=len, reverse=True))
                + r")(?![A-Za-z0-9_])"
            )
            value = re.sub(pattern, lambda match: identifier + "_" + match.group(1), value)
        return value

    CASES.append(namespace(item))


